Here's an example of a simple banking system class with methods to deposit and withdraw money:

```java
import java.util.HashMap;
import java.util.Map;

public class BankingSystem {
    private Map<String, Double> accounts;

    public BankingSystem() {
        this.accounts = new HashMap<>();
    }

    public void createAccount(String accountNumber, double initialBalance) {
        if (accounts.containsKey(accountNumber)) {
            System.out.println("Account already exists.");
        } else {
            accounts.put(accountNumber, initialBalance);
            System.out.println("Account created successfully.");
        }
    }

    public void deposit(String accountNumber, double amount) {
        if (accounts.containsKey(accountNumber)) {
            accounts.put(accountNumber, accounts.get(accountNumber) + amount);
            System.out.println("Deposit successful.");
        } else {
            System.out.println("Account does not exist.");
        }
    }

    public void withdraw(String accountNumber, double amount) {
        if (accounts.containsKey(accountNumber)) {
            if (amount <= accounts.get(accountNumber)) {
                accounts.put(accountNumber, accounts.get(accountNumber) - amount);
                System.out.println("Withdrawal successful.");
            } else {
                System.out.println("Insufficient balance.");
            }
        } else {
            System.out.println("Account does not exist.");
        }
    }

    public static void main(String[] args) {
        BankingSystem banking = new BankingSystem();
        banking.createAccount("12345", 1000.0);
        banking.deposit("12345", 500.0);
        banking.withdraw("12345", 200.0);
        banking.withdraw("12345", 1500.0); // Insufficient balance
    }
}
