import java.util.ArrayList;
import java.util.HashMap;

public class ShoppingCart {
    private ArrayList<CartItem> items;

    public ShoppingCart() {
        this.items = new ArrayList<>();
    }

    public void addItem(CartItem item) {
        items.add(item);
        System.out.println("Item added to cart.");
    }

    public void removeItem(String itemNumber) {
        for (int i = 0; i < items.size(); i++) {
            if (items.get(i).getItemNumber() == itemNumber) {
                items.remove(i);
                System.out.println("Item removed from cart.");
                return;
            }
        }
        System.out.println("Item not found in cart.");
    }

    public void displayCart() {
        System.out.println("Current Cart:");
        for (CartItem item : items) {
            System.out.println(item.toString());
        }
    }

    public static class CartItem {
        private String itemNumber;
        private double quantity;

        public CartItem(String itemNumber, double quantity) {
            this.itemNumber = itemNumber;
            this.quantity = quantity;
        }

        @Override
        public String toString() {
            return "Item Number: " + itemNumber + ", Quantity: " + quantity;
        }
    }

    public static void main(String[] args) {
        ShoppingCart shoppingCart = new ShoppingCart();
        shoppingCart.addItem(new CartItem("12345", 2));
        shoppingCart.addItem(new CartItem("67890", 1));
        shoppingCart.displayCart();
        shoppingCart.removeItem("12345");
        shoppingCart.displayCart();
    }
}
